    hwif_out.length.bytes.swmod <= decoded_reg_strb.length and decoded_req_is_wr and or_reduce(decoded_wr_biten(31 downto 0));

    -- Field: txfifo_csr.write.data
    process(all)
        variable next_c: std_logic_vector(31 downto 0);
        variable load_next_c: std_logic;
    begin
        next_c := field_storage.write.data.value;
        load_next_c := '0';
        if decoded_reg_strb.write and decoded_req_is_wr then -- SW write
            next_c := (field_storage.write.data.value and not decoded_wr_biten(31 downto 0)) or (decoded_wr_data(31 downto 0) and decoded_wr_biten(31 downto 0));
            load_next_c := '1';
        end if;
        field_combo.write.data.next_q <= next_c;
        field_combo.write.data.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.write.data.value <= 32x"0";
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.write.data.value <= 32x"0";
            else
                if field_combo.write.data.load_next then
                    field_storage.write.data.value <= field_combo.write.data.next_q;
                end if;
            end if;
        end if;
    end process;
    hwif_out.write.data.value <= field_storage.write.data.value;
    hwif_out.write.data.swmod <= decoded_reg_strb.write and decoded_req_is_wr and or_reduce(decoded_wr_biten(31 downto 0));

    -- Field: txfifo_csr.dst.id
    process(all)
        variable next_c: std_logic_vector(31 downto 0);
        variable load_next_c: std_logic;
    begin
        next_c := field_storage.dst.id.value;
        load_next_c := '0';
        if decoded_reg_strb.dst and decoded_req_is_wr then -- SW write
            next_c := (field_storage.dst.id.value and not decoded_wr_biten(31 downto 0)) or (decoded_wr_data(31 downto 0) and decoded_wr_biten(31 downto 0));
            load_next_c := '1';
        end if;
        field_combo.dst.id.next_q <= next_c;
        field_combo.dst.id.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.dst.id.value <= 32x"0";
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.dst.id.value <= 32x"0";
            else
                if field_combo.dst.id.load_next then
                    field_storage.dst.id.value <= field_combo.dst.id.next_q;
                end if;
            end if;
        end if;
    end process;
    hwif_out.dst.id.value <= field_storage.dst.id.value;

    ----------------------------------------------------------------------------
    -- Write response
    ----------------------------------------------------------------------------
    cpuif_wr_ack <= decoded_req and decoded_req_is_wr;
    -- Writes are always granted with no error response
    cpuif_wr_err <= '0';

    ----------------------------------------------------------------------------
    -- Readback
    ----------------------------------------------------------------------------
    rd_mux_addr <= unsigned(decoded_addr);

    process(all)
        variable readback_data_var : std_logic_vector(31 downto 0);
    begin
        readback_data_var := (others => '0');
        if rd_mux_addr = 16#4# then
            readback_data_var(0) := field_storage.ier.txc.value;
            readback_data_var(1) := field_storage.ier.wrf.value;
            readback_data_var(2) := field_storage.ier.tle.value;
        end if;
        if rd_mux_addr = 16#8# then
            readback_data_var(0) := field_storage.isr.txc.value;
            readback_data_var(1) := field_storage.isr.wrf.value;
            readback_data_var(2) := field_storage.isr.tle.value;
        end if;
        if rd_mux_addr = 16#C# then
            readback_data_var(31 downto 0) := hwif_in.fill.usedw.next_q;
        end if;
        if rd_mux_addr = 16#10# then
            readback_data_var(31 downto 0) := field_storage.length.bytes.value;
        end if;
        if rd_mux_addr = 16#18# then
            readback_data_var(31 downto 0) := field_storage.dst.id.value;
        end if;
        readback_data <= readback_data_var;
        readback_done <= decoded_req and not decoded_req_is_wr;
        readback_err <= '0';
    end process;

    cpuif_rd_ack <= readback_done;
    cpuif_rd_data <= readback_data;
    cpuif_rd_err <= readback_err;
end architecture rtl;
